from summary_lib import *
from helpers import P

def add(chap, sub):
    chap("F", "Formula Sheet (all readings)", "revise last", 5)
    sub("Equity: P1–P3", 5,
      F("Tracking error (active risk) = SD(Rₚ − Rᵦ)\nActive return R_A = Σ (wₚᵢ − wᵦᵢ) Rᵢ = Σ (βₚₖ − βᵦₖ) F_k + α + ε\nE(R_A) = IC × √BR × σ_A × TC   (BR per year)\nActive Share = ½ Σ |wₚᵢ − wᵦᵢ| ; overlap = 1 − Active Share\nσ²_A = active factor risk + active idiosyncratic risk\nCVᵢ = Σⱼ wᵢ wⱼ Cov(i,j) = wᵢ × Cov(rᵢ, rₚ) ; share = CVᵢ / σₚ²\nFactor contribution = Σⱼ βᵢ βⱼ Cov(Fᵢ, Fⱼ)\nCAVᵢ = (wₚᵢ − wᵦᵢ) Σⱼ (wₚⱼ − wᵦⱼ) Cov(RAᵢ, RAⱼ)\nR_g ≈ R_a − σ²/2\nGross = long + |short| ; net = long − short\nStandardised factor score z = (x − mean) / SD\nPEG = P/E ÷ growth (%) ; pairs spread = ln(P_A / P_B)\nMax position = ADV × max % of ADV ; AUM limit = max $ position ÷ max weight"))
    sub("Liability-driven & index-based: P4", 5,
      F("MD = Macaulay duration / (1 + periodic YTM)\n%ΔValue ≈ −MD × ΔY + ½ C × ΔY²\nBPV = MD × Value × 0.0001\nFutures BPV ≈ BPV_CTD / CF_CTD\nN_futures = (BPV_L − BPV_A) / BPV_futures   (+ buy, − sell)\nSwap BPV per 100 NP = (D_fixed − D_float) × 100 × 0.0001\nSwap NP = BPV gap / (swap BPV per 100 / 100)\nSwaption premium = NP × premium (bp)\n1/32 on 100,000 par = $31.25\nPortfolio convexity = Σ [t (t+1) w] / (1 + IRR_periodic)² ; duration = Σ t w (÷2 if semiannual)") +
      K("Single liability: PVA ≥ PVL · D_Mac = due date · minimise convexity · rebalance",
        "Multiple: PVA ≥ PVL · BPV_A = BPV_L · convexity A &gt; L (not by much) · rebalance"))
    sub("Yield curve: P5", 5,
      F("Slope = long − short yield\nButterfly spread = −short + 2 × medium − long\nReturn ≈ coupon/price + rolldown + (−MD ΔY + ½C ΔY²) + (−MD ΔS + ½C ΔS²) + currency\nEffective duration = (PV₋ − PV₊) / (2 × Δcurve × PV₀)\nEffective convexity = (PV₋ + PV₊ − 2PV₀) / (Δcurve² × PV₀)\nKey rate duration = −(1/PV) × ΔPV / Δr_k ; zero-coupon KRD = MD × weight\nDuration-neutral hedge: MV₂ = BPV₁ / (MD₂ × 0.0001)\nR_DC = (1 + R_FC)(1 + R_FX) − 1   (R_FX from DC/FC quote)\nCIRP forward F = S × [(1 + r_DC)/(1 + r_FC)]^T\nRolling 90-day deposits: Π(1 + rᵢ/4) − 1"))
    sub("Credit: P6", 5,
      F("Fair spread ≈ POD × LGD ; LGD = 1 − recovery\nInterpolation weight on longer maturity = (M − S)/(L − S)\nYield spread = YTM − nearest govt ; g-spread = YTM − interpolated govt\ni-spread = YTM − interpolated swap rate ; ASW = coupon − interpolated swap rate\nCDS basis = CDS spread − z-spread\nFRN: EffRateDur = (PV₋ − PV₊)/(2 ΔMRR PV₀) ; EffSpreadDur = (PV₋ − PV₊)/(2 ΔDM PV₀)\nEffSpreadDur = (PV₋ − PV₊)/(2 Δspread PV₀) ; EffSpreadCon = (PV₋ + PV₊ − 2PV₀)/(Δspread² PV₀)\n%Δprice ≈ −EffSpreadDur × Δs + ½ EffSpreadCon × Δs²\nDTS = EffSpreadDur × spread ; Δvalue (bp) ≈ −DTS × %Δ index OAS\nExpected excess spread ≈ spread − EffSpreadDur × Δspread − POD × LGD (per period)\nAltman z = 1.2 WC/TA + 1.4 RE/TA + 3.3 EBIT/TA + 0.6 MVE/TL + 1.0 Sales/TA\nParametric VaR = z × σ_period × duration × value (5%: 1.65, 1%: 2.33 ; σ_month = σ_year/√12)\nCDS upfront ≈ (CDS spread − fixed coupon) × EffSpreadDur × notional\nCDS price ≈ 1 + (fixed coupon − CDS spread) × EffSpreadDur ; Δprice ≈ −ΔCDS spread × EffSpreadDur\nCDS BPV = notional × EffSpreadDur × 0.0001"))
    sub("Trading: P7 and case: P8", 5,
      F("IS = paper return − actual return (bp of paper cost)\nDelay = filled × (arrival − decision) ; trading = filled × (execution − arrival)\nOpportunity = unfilled × (close − decision) ; fixed fees = commissions\n(flip signs for sells)\nCost (bp) = Side × (P_exec − P_bench)/P_bench × 10,000   (buy +1, sell −1)\nIndex cost (bp) = Side × (index VWAP − index arrival)/index arrival × 10,000\nMarket-adjusted cost = arrival cost − β × index cost\nAdded value = arrival cost − pre-trade estimate\nIlliquid price = marketable price − put price\nSpending (smoothed) = w × prior spending + (1 − w) × rate × prior MV\nFinancing cost = exposure × % borrowed × financing rate"))
